# Let me systematically identify all the transformations needed
inputs = ['gfiwk', 'wbj', 'bfh', 'dwzaf', 'gdaj']
outputs = ['ghibk', 'bbj', 'bh', 'dbzah', 'gdaj']

# Build a set of transformations needed
transformations = {}

for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]

    # Create a mapping of what changed
    min_len = min(len(inp), len(out))

    # Check character by character for substitutions
    j = 0
    while j < min_len:
        if inp[j] != out[j]:
            if inp[j] not in transformations:
                transformations[inp[j]] = out[j]
            elif transformations[inp[j]] != out[j]:
                # Multiple different transformations for same char - need to see which one applies
                pass
        j += 1

    # Handle length differences (deletions/insertions)
    if len(inp) > len(out):
        # Some characters were deleted
        for k in range(len(out), len(inp)):
            if inp[k] not in transformations:
                transformations[inp[k]] = ""
    elif len(out) > len(inp):
        # Some characters were inserted - need to track this too
        for k in range(len(inp), len(out)):
            if out[k] not in transformations.values():
                # This is an insertion, not a transformation
                pass

print("Transformations found:")
for old, new in transformations.items():
    print(f"'{old}' -> '{new}'")

# Now let me trace through what replacements would work
print("\nTrying to figure out minimal replacement sequence...")

